  --bg-color: #0f0f0f;
  --surface-color: #1a1a1a;
  --surface-color-light: #2a2a2a;
  --primary-color: #c5a059;
  --primary-color-dark: #a68545;
  --text-primary: #ffffff;
  --text-secondary: #a0a0a0;
  --error-color: #cf6679;
  --focus-outline: 2px solid var(--primary-color);
  --focus-offset: 4px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Accessibility Utilities */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--primary-color);
  color: var(--bg-color);
  padding: 8px;
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
  outline: var(--focus-outline);
  outline-offset: 0;
}

/* Focus Management */
:focus-visible {
  outline: var(--focus-outline);
  outline-offset: var(--focus-offset);
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.section {
  padding: 60px 0;
}

.section-heading {
  font-size: 2rem;
  margin-bottom: 30px;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 2px;
}

/* Header */
header {
  border-bottom: 1px solid var(--surface-color-light);
  padding: 20px 0;
  background-color: var(--bg-color);
  position: sticky;
  top: 0;
  z-index: 50;
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--primary-color);
  letter-spacing: 4px;
}

nav ul {
  list-style: none;
  display: flex;
  gap: 30px;
  margin: 0;
  padding: 0;
}

nav a {
  font-weight: 500;
  text-transform: uppercase;
  font-size: 0.9rem;
  transition: color 0.2s;
}

nav a:hover {
  color: var(--primary-color);
}

.header-actions {
  display: flex;
  gap: 20px;
  align-items: center;
}

/* Hero */
.hero {
  height: 80vh;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  display: flex;
  align-items: center;
  position: relative;
}

.hero::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(to right, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.2) 100%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 600px;
}

.hero h1 {
  font-size: 3.5rem;
  margin-bottom: 20px;
  line-height: 1.2;
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 30px;
  color: var(--text-secondary);
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 12px 30px;
  font-weight: bold;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 0.9rem;
}

.btn-primary {
  background-color: var(--primary-color);
  color: var(--bg-color);
}

.btn-primary:hover {
  background-color: var(--primary-color-dark);
}

.btn-outline {
  background-color: transparent;
  border: 1px solid var(--text-primary);
  color: var(--text-primary);
}

.btn-outline:hover {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

/* Product Cards */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 40px;
}

.product-card {
  background-color: var(--surface-color);
  transition: transform 0.3s;
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-5px);
}

.product-image {
  aspect-ratio: 4/5;
  background-color: #222;
  overflow: hidden;
}

.product-info {
  padding: 20px;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.product-name {
  font-size: 1.1rem;
  margin: 0 0 10px 0;
}

.product-price {
  font-weight: bold;
  color: var(--primary-color);
  margin-bottom: 15px;
}

.deal-price {
  color: var(--error-color);
  margin-right: 10px;
}

.original-price {
  text-decoration: line-through;
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.add-to-cart {
  margin-top: auto;
  width: 100%;
}

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

@media (max-width: 768px) {
  .editorial-grid {
    grid-template-columns: 1fr;
  }
}

.editorial-text h3 {
  font-size: 2rem;
  margin-bottom: 20px;
}

/* Footer */
footer {
  background-color: var(--surface-color);
  padding: 60px 0 30px 0;
  margin-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 40px;
  margin-bottom: 40px;
}

.footer-col h4 {
  text-transform: uppercase;
  margin-bottom: 20px;
  font-size: 1rem;
  color: var(--primary-color);
}

.footer-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--text-secondary);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  text-align: center;
  padding-top: 30px;
  border-top: 1px solid var(--surface-color-light);
  color: var(--text-secondary);
  font-size: 0.8rem;
}

/* Search Form */
.search-form {
  position: relative;
}

.search-input {
  background: var(--surface-color-light);
  border: none;
  color: var(--text-primary);
  padding: 8px 15px;
  border-radius: 20px;
  width: 150px;
  transition: width 0.3s;
}

.search-input:focus {
  width: 250px;
  outline: var(--focus-outline);
}
